import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { io, Socket } from 'socket.io-client';
import { Match, LeaderboardEntry, Notification } from '../types';

interface SocketContextType {
  socket: Socket | null;
  isConnected: boolean;
  liveMatches: Match[];
  leaderboardUpdates: LeaderboardEntry[];
  notifications: Notification[];
  joinMatchRoom: (matchId: string) => void;
  leaveMatchRoom: (matchId: string) => void;
  markNotificationAsRead: (notificationId: string) => void;
}

const SocketContext = createContext<SocketContextType | undefined>(undefined);

export const useSocket = () => {
  const context = useContext(SocketContext);
  if (context === undefined) {
    throw new Error('useSocket must be used within a SocketProvider');
  }
  return context;
};

interface SocketProviderProps {
  children: ReactNode;
}

export const SocketProvider: React.FC<SocketProviderProps> = ({ children }) => {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [liveMatches, setLiveMatches] = useState<Match[]>([]);
  const [leaderboardUpdates, setLeaderboardUpdates] = useState<LeaderboardEntry[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    // Mock socket connection - in a real app, this would connect to your backend
    const mockSocket = {
      connected: true,
      on: (event: string, callback: Function) => {
        // Mock event handlers
        if (event === 'connect') {
          setTimeout(() => callback(), 1000);
        } else if (event === 'match_update') {
          // Simulate match updates every 30 seconds
          setInterval(() => {
            callback({
              matchId: 'match-1',
              homeScore: Math.floor(Math.random() * 3),
              awayScore: Math.floor(Math.random() * 3),
              minute: Math.floor(Math.random() * 90) + 1
            });
          }, 30000);
        } else if (event === 'leaderboard_update') {
          // Simulate leaderboard updates
          setInterval(() => {
            callback([
              {
                id: 'user-1',
                username: 'champion_player',
                avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150',
                points: Math.floor(Math.random() * 200) + 100,
                rank: 1
              }
            ]);
          }, 45000);
        }
      },
      emit: (event: string, data: any) => {
        console.log(`Mock socket emit: ${event}`, data);
      },
      disconnect: () => {
        setIsConnected(false);
      }
    } as any;

    setSocket(mockSocket);
    setIsConnected(true);

    // Mock initial notifications
    setNotifications([
      {
        id: 'notif-1',
        userId: 'user-1',
        type: 'result',
        title: 'Contest Result',
        message: 'You finished 3rd in Premier League Contest!',
        isRead: false,
        createdAt: new Date(Date.now() - 1000 * 60 * 30).toISOString()
      },
      {
        id: 'notif-2',
        userId: 'user-1',
        type: 'match_start',
        title: 'Match Starting',
        message: 'Chelsea vs Arsenal starts in 15 minutes',
        isRead: false,
        createdAt: new Date(Date.now() - 1000 * 60 * 10).toISOString()
      }
    ]);

    return () => {
      if (mockSocket) {
        mockSocket.disconnect();
      }
    };
  }, []);

  const joinMatchRoom = (matchId: string) => {
    if (socket) {
      socket.emit('join_match', { matchId });
    }
  };

  const leaveMatchRoom = (matchId: string) => {
    if (socket) {
      socket.emit('leave_match', { matchId });
    }
  };

  const markNotificationAsRead = (notificationId: string) => {
    setNotifications(prev => 
      prev.map(notif => 
        notif.id === notificationId 
          ? { ...notif, isRead: true } 
          : notif
      )
    );
  };

  const value = {
    socket,
    isConnected,
    liveMatches,
    leaderboardUpdates,
    notifications,
    joinMatchRoom,
    leaveMatchRoom,
    markNotificationAsRead
  };

  return (
    <SocketContext.Provider value={value}>
      {children}
    </SocketContext.Provider>
  );
};
